cat > app/Http/Controllers/LocaleController.ts <<'EOF'
import { Controller } from '@guren/core'
import type { LocalePayload } from '../Validators/LocaleValidator.js'

const ONE_YEAR_SECONDS = 60 * 60 * 24 * 365

// Only the path of the Referer is kept, so the redirect can never leave the site.
function refererPath(referer: string | undefined): string {
  if (!referer) return '/'
  try {
    const url = new URL(referer)
    return `${url.pathname}${url.search}${url.hash}`
  } catch {
    return '/'
  }
}

export default class LocaleController extends Controller {
  async update(): Promise<Response> {
    const { body } = this.validated('locale.update') as { body: LocalePayload }

    return this.redirect(refererPath(this.ctx.req.header('Referer')), {
      headers: {
        'Set-Cookie': `locale=${body.locale}; Path=/; Max-Age=${ONE_YEAR_SECONDS}; SameSite=Lax`,
      },
    })
  }
}
EOF
